do $$ begin
 if exists(select 1 from public.catalogue_cards t join desired_catalogue_cards e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.checklist_order is distinct from e.checklist_order or t.category is distinct from e.category or t.subset_code is distinct from e.subset_code or t.card_number is distinct from e.card_number or t.display_name is distinct from e.display_name or t.subject_1 is distinct from e.subject_1 or t.subject_2 is distinct from e.subject_2 or t.roster is distinct from e.roster or t.rookie is distinct from e.rookie or t.parallel_group is distinct from e.parallel_group or t.image_status is distinct from e.image_status or t.pricing_status is distinct from e.pricing_status or t.source_url is distinct from e.source_url or t.notes is distinct from e.notes)
 then raise exception 'Conflicting catalogue_cards identity; refusing overwrite'; end if;
end $$;
insert into public.catalogue_cards(id,set_id,checklist_order,category,subset_code,card_number,display_name,subject_1,subject_2,roster,rookie,parallel_group,image_status,pricing_status,source_url,notes) select id,set_id,checklist_order,category,subset_code,card_number,display_name,subject_1,subject_2,roster,rookie,parallel_group,image_status,pricing_status,source_url,notes from desired_catalogue_cards on conflict do nothing;
